-- No class/level hand-in gate. Quest faction prerequisites are intentionally bypassed.
-- Recipe quantities/rewards are P99-reviewed; reward magnitudes and limitations are documented in docs/velious-armor-quests.md.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Well met, " .. e.other:GetRaceName() .. "! I am Captain Njall, commander of the city gaurds here in Thurgadin. If ye seek ta join our ranks, I welcome ye with open arms and have an offer to make if you are interested. If ye seek to be our enemy, I hope ye can run swifter than my archers arrows.")
  end
  if e.message:findi("i am interested") then
    e.self:Say("Aye, I thought ye might be. My elite warriors are in sore need of some enchanted armor. Unfortunately, I can’t spare the men to go out and fetch me the components. If you can do this for me, I’ll gladly reward you with a piece of it. I need materials for a helm, a breastplate, armplates, bracers, gauntlets, greaves, and boots.")
  end
  if e.message:findi("helm") then
    e.self:Say("To create a piece of armor to protect your skull I will require three pieces of crushed coral as well as a corroded plate helmet.")
  end
  if e.message:findi("breastplate") then
    e.self:Say("For the breastplate, I will need a corroded breastplate and three flawless diamonds. Once I have them in my possession it will not take long to craft a sturdy breastplate.")
  end
  if e.message:findi("armplates") then
    e.self:Say("Protection for your arms will come at the price of a set of corroded plate vambraces and three flawed emeralds.")
  end
  if e.message:findi("bracers") then
    e.self:Say("For the bracers, I will require a corroded plate bracer and a set of three crushed flame emeralds. Return to me if you happen to find these things in your travels.")
  end
  if e.message:findi("gauntlets") then
    e.self:Say("Protecting your hands is very important. I can forge protection for your hands if you bring me a pair of corroded plate gauntlets and three crushed topaz.")
  end
  if e.message:findi("greaves") then
    e.self:Say("A set of corroded plate greaves might be salvageable if you were to find three flawed sea sapphires. With the right techniques almost anything is possible.")
  end
  if e.message:findi("boots") then
    e.self:Say("Boots made for battle are not always the most comfortable available. However if you seek a fine set for battle bring me a set of corroded plate boots and three pieces of crushed black marble.")
  end
end

